95	impl Visitor for AnyExportInTestVisitor {
96	    type Language = JsLanguage;
97	
98	    fn visit(
99	        &mut self,
100	        event: &biome_rowan::WalkEvent<biome_rowan::SyntaxNode<Self::Language>>,
101	        mut ctx: biome_analyze::VisitorContext<Self::Language>,
102	    ) {
103	        match event {
104	            WalkEvent::Enter(node) => {
105	                if let Some(maybe_export) = MaybeExport::cast_ref(node) {
106	                    if maybe_export.is_export() {
107	                        self.exports.push(maybe_export);
108	                    }
109	                }
110	
111	                if !self.has_test {
112	                    if let Some(call_expr) = JsCallExpression::cast_ref(node) {
113	                        self.has_test = call_expr.is_test_call_expression().unwrap_or(false);
114	                    }
115	                }
116	            }
117	            WalkEvent::Leave(node) => {
118	                if AnyJsRoot::cast_ref(node).is_some() && self.has_test {
119	                    for export in self.exports.iter() {
120	                        ctx.match_query(AnyExportInTest(export.clone()));
121	                    }
122	                }
123	            }
124	        }
125	    }
126	}
